#include <iostream>
using namespace std;

struct Node {
    int data;
    Node* left;
    Node* right;
    Node(int d) : data(d), left(nullptr), right(nullptr) {}
};

Node* insert(Node* node, int value) {
    if (node == nullptr) {
        return new Node(value);
    }
    if (value < node->data) {
        node->left = insert(node->left, value);
    } else {
        node->right = insert(node->right, value);
    }
    return node;
}

void preOrder(Node* node) {
    if (node == nullptr) {
        return;
    }
    cout << node->data << " ";
    preOrder(node->left);
    preOrder(node->right);
}

void destroy(Node* node) {
    if (node == nullptr) {
        return;
    }
    destroy(node->left);
    destroy(node->right);
    cout << "delete " << node->data << endl;
    delete node;
}

int main() {
    Node* root = nullptr;
    int values[] = {50, 30, 70, 20, 40, 60};
    for (int i = 0; i < 6; i++) {
        root = insert(root, values[i]);
    }
    preOrder(root);
    cout << endl;
    destroy(root);
    return 0;
}
